// Images des dossiers de pré-commercialisation, embarquées en base64.
// Pourquoi base64 et pas un chemin /properties/... : la prod (Replit Autoscale)
// ne sert pas fiablement public/properties/. En embarquant l'image dans la
// donnée (comme le faisaient les dossiers HTML d'origine), elle est toujours
// présente, indépendamment du serveur de fichiers statiques.
// Généré par scripts/_gen-dossier-images.mjs depuis public/properties/<id>/.

export const LOT1_PLAN = 'data:image/jpeg;base64,';
export const LOT1_AVANT = 'data:image/jpeg;base64,';
export const LOT2_PLAN = 'data:image/jpeg;base64,';
export const LOT2_AVANT = 'data:image/jpeg;base64,';
